      "category": "architecture_interaction",
      "rationale": "Reduce the feed-forward expansion from 4× to 2× hidden width across all four category models to test whether lower capacity reduces overfitting on short histories. Preserve bidirectional attention, two blocks, two heads, pre-norm residuals, final LayerNorm, embeddings, masking, readout, loss and optimizer. The embedded predictor imports this same model class, so checkpoint shapes remain consistent.",
      "edits": [
        {
          "find": "            dim_feedforward=hidden_units * 4,",
          "replace": "            dim_feedforward=hidden_units * 2,"
        }
      ]
    }
  ],
  "change_summary": "Narrow BERT4Rec feed-forward layers from 4× to 2× hidden width, retaining one independently trained model per category and compatible predictor construction."
}
